findings.codeql_raw_query:
/**
 * @name Detect use of eval/exec with potential user-controlled input
 * @description Finds flows from remote inputs to eval/exec calls
 * @kind path-problem
 * @problem.severity error
 * @id py/pluggy/eval-exec-injection
 * @tags security
 *       external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module EvalExecConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(CodeExecution ce |
      sink = ce.getCode()
    )
  }
}

module EvalExecFlow = TaintTracking::Global<EvalExecConfig>;
import EvalExecFlow::PathGraph

from EvalExecFlow::PathNode source, EvalExecFlow::PathNode sink
where EvalExecFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Code injection from $@.", source.getNode(), "user input"
